from research_helpers import *
base='https://electronics-electric.basf.com/global/en/electronics/'
a=ev(base+'products/selectipur','Named semiconductor process chemical and etchant families reviewed; no concentration/purity permutations invented.')
b=ev(base+'semiconductors_solutions/chemical-mechanical-planarization','Three named PLANAPUR CMP families.')
c=ev(base+'products/fotopur','Four named photolithography ancillary families.')
d=ev(base+'semiconductors_solutions/wet-deposition','Three named wet-deposition chemistry families.')
e=ev('https://download.basf.com/p1/EN_StaticDocuments_33999/en/Technical_Information','Separate technical document resolves exact Natuphos E20000Gb suffix; not footnote.')
f=ev('https://download.basf.com/p1/EN_StaticDocuments_35199/en/Technical_Information','Separate technical document confirms Natugrain TS2.5G spelling; catalogue typo not propagated.')
products=[]
for name in ['Hydrogen peroxide','Isopropyl alcohol','Ammonium hydroxide','Sulfuric acid','Hydrochloric acid','Nitric acid','Acetic acid','Hydrofluoric acid','Phosphoric acid','Ammonium fluoride']:products.append(p('BASF SELECTIPUR '+name,'Semiconductor-grade process chemical offering.',a,life='commercial',typ='product',sector='semiconductors',sub='materials_and_packaging',roles=['commercial_partner']))
for name in ['SiO2 BOE/BHF Etch Series','Silicon and Poly Silicon Etch Series','Si3N4 Etch Series','TiN Etch Series','Spin Etch Series','Al Etch Series','Cu Etch Series','Ni Etch Series','Ti Etch Series','Stack Etch Series','Q-Etch','Fence Etch']:products.append(p('BASF SELECTIPUR '+name,'Semiconductor wet-etch chemistry family.',a,life='commercial',typ='product',sector='semiconductors',sub='materials_and_packaging',roles=['commercial_partner']))
for name,desc,src in [('PLANAPUR S Series','Oxide CMP chemistry family.',b),('PLANAPUR C Series','Copper CMP chemistry family.',b),('PLANAPUR T Series','Barrier CMP chemistry family.',b),('FOTOPUR C Series','Lithography rinse chemistry family.',c),('FOTOPUR R Series','Residue-removal chemistry family.',c),('FOTOPUR D Series','Lithography developer chemistry family.',c),('FOTOPUR S Series','Lithography stripping chemistry family.',c),('CUPUR ECP Series','Copper electroplating chemistry family.',d),('CUPUR TSV Series','Through-silicon-via deposition chemistry family.',d),('CUPUR Capping Series','Selective capping deposition chemistry family.',d)]:products.append(p('BASF '+name,desc,src,life='commercial',typ='product',sector='semiconductors',sub='materials_and_packaging',roles=['commercial_partner']))
products += [p('Natuphos E 20000 Gb','Granulated feed phytase grade.',e,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']),p('Natugrain TS 2.5 G','Granulated xylanase/glucanase feed-enzyme grade.',f,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner'])]
co=dict(company_id='cmp_2fa8cc21-8e08-4f1b-aa3c-3cdc02359ffa',products=products,evidence=[a,b,c,d,e,f],status='partial',coverage_note='76 BASF offerings total: previous 42 plus 32 semiconductor process-chemical offerings/families and two resolved feed-enzyme grades. SELECTIPUR acids and formulation families are manufacturer-specific offerings, no purity/concentration permutations invented. Natuphos E20000Gb suffix confirmed and Natugrain TS2.5G catalogue typo resolved with separate official technical documents. Partial: exact semiconductor formulation codes, further biotech/fermentation products, battery binders/electrolytes/recycling technologies, historical storage systems and legacy portfolio remain.')
assert len(products)==34
(out/'batch-0391.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
